// The outlined wordmarks (brand board lettering, generated by scripts/gen_wordmark.py): "olive deck" for the
// product and "sideck" for the edge organizer, drawn from vector data so they need no font.
#pragma once

#include <windows.h>

namespace wp {

class Canvas;

enum class Mark { OliveDeck, Sideck };

// Size in px of the wordmark drawn `height` px tall (ascender top to the lowest overshoot).
SIZE WordmarkSize(int height, Mark m = Mark::OliveDeck);
// Draws it with its top-left at (x, y).
void DrawWordmark(Canvas& c, int x, int y, int height, COLORREF color, Mark m = Mark::OliveDeck);

}  // namespace wp
